CREATE TABLE rpt."Reports" (
    "ReportId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "ReportKey" character varying(60) NOT NULL,
    "Title" character varying(120) NOT NULL,
    "Module" integer NOT NULL,
    "Description" character varying(500) NULL,
    "RequiredPermission" character varying(60) NOT NULL,
    "IsActive" boolean NOT NULL,
    "SortOrder" integer NOT NULL,
    "CreatedBy" uuid NULL,
    "CreatedAt" timestamp with time zone NULL,
    "ModifiedBy" uuid NULL,
    "ModifiedAt" timestamp with time zone NULL,
    "OrgId" uuid NOT NULL,
    CONSTRAINT "PK_Reports" PRIMARY KEY ("ReportId")
);

CREATE TABLE rpt."ReportDetails" (
    "ReportDetailId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "ReportId" bigint NOT NULL,
    "ColumnKey" character varying(60) NOT NULL,
    "Header" character varying(120) NOT NULL,
    "DataType" integer NOT NULL,
    "IsDefault" boolean NOT NULL,
    "IsFilterable" boolean NOT NULL,
    "IsSortable" boolean NOT NULL,
    "IsGroupable" boolean NOT NULL,
    "IsPivotable" boolean NOT NULL,
    "DefaultAggregate" integer NOT NULL,
    "Alignment" integer NOT NULL,
    "Width" integer NULL,
    "SortOrder" integer NOT NULL,
    "IsPrimary" boolean NOT NULL,
    "IsHidden" boolean NOT NULL,
    "CreatedBy" uuid NULL,
    "CreatedAt" timestamp with time zone NULL,
    "ModifiedBy" uuid NULL,
    "ModifiedAt" timestamp with time zone NULL,
    "OrgId" uuid NOT NULL,
    CONSTRAINT "PK_ReportDetails" PRIMARY KEY ("ReportDetailId")
);

CREATE TABLE rpt."ReportViews" (
    "ReportViewId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "ReportId" bigint NOT NULL,
    "ViewName" character varying(80) NOT NULL,
    "OwnerUserId" uuid NULL,
    "IsDefault" boolean NOT NULL,
    "LayoutJson" jsonb NOT NULL,
    "CreatedBy" uuid NULL,
    "CreatedAt" timestamp with time zone NULL,
    "ModifiedBy" uuid NULL,
    "ModifiedAt" timestamp with time zone NULL,
    "OrgId" uuid NOT NULL,
    CONSTRAINT "PK_ReportViews" PRIMARY KEY ("ReportViewId")
);

ALTER TABLE rpt."ReportDetails" ADD CONSTRAINT "FK_ReportDetails_Reports_ReportId" FOREIGN KEY ("ReportId") REFERENCES rpt."Reports" ("ReportId") ON DELETE CASCADE;
ALTER TABLE rpt."ReportViews" ADD CONSTRAINT "FK_ReportViews_Reports_ReportId" FOREIGN KEY ("ReportId") REFERENCES rpt."Reports" ("ReportId") ON DELETE CASCADE;

CREATE INDEX "IX_ReportDetails_Order" ON rpt."ReportDetails" ("OrgId", "ReportId", "SortOrder");
CREATE INDEX "IX_ReportDetails_OrgId" ON rpt."ReportDetails" ("OrgId");
CREATE UNIQUE INDEX "IX_ReportDetails_OrgId_ReportId_ColumnKey" ON rpt."ReportDetails" ("OrgId", "ReportId", "ColumnKey");
CREATE INDEX "IX_ReportDetails_ReportId" ON rpt."ReportDetails" ("ReportId");
CREATE UNIQUE INDEX "IX_ReportViews_Default" ON rpt."ReportViews" ("OrgId", "ReportId", "OwnerUserId") WHERE "IsDefault" = true;
CREATE UNIQUE INDEX "IX_ReportViews_Name" ON rpt."ReportViews" ("OrgId", "ReportId", "OwnerUserId", "ViewName");
CREATE INDEX "IX_ReportViews_OrgId" ON rpt."ReportViews" ("OrgId");
CREATE INDEX "IX_ReportViews_ReportId" ON rpt."ReportViews" ("ReportId");
CREATE INDEX "IX_Reports_Order" ON rpt."Reports" ("OrgId", "Module", "SortOrder");
CREATE INDEX "IX_Reports_OrgId" ON rpt."Reports" ("OrgId");
CREATE UNIQUE INDEX "IX_Reports_OrgId_ReportKey" ON rpt."Reports" ("OrgId", "ReportKey");

ALTER TABLE rpt."Reports" ENABLE ROW LEVEL SECURITY;
CREATE POLICY reports_org_isolation ON rpt."Reports" USING ("OrgId" = current_setting('app.current_org_id', true)::uuid);

ALTER TABLE rpt."ReportDetails" ENABLE ROW LEVEL SECURITY;
CREATE POLICY reportdetails_org_isolation ON rpt."ReportDetails" USING ("OrgId" = current_setting('app.current_org_id', true)::uuid);

ALTER TABLE rpt."ReportViews" ENABLE ROW LEVEL SECURITY;
CREATE POLICY reportviews_org_isolation ON rpt."ReportViews" USING ("OrgId" = current_setting('app.current_org_id', true)::uuid);